class DecodeTests(unittest.TestCase):
    def test_days_follow_the_addon_rules(self):
        text = ";".join([
            "2501,10,20,15,5,2,o", "2500,30,40,35,9,1,a", "2501,8,25,9,7,2,o",   # same day, own: lo min, hi max, ties by last
            "2502,50,60,55,1,1,a", "2502,70,80,75,1,1,o",                        # own beats import whatever the order
            "2503,5,4,4,1,1,o", "2503,1,2,1,1,1,x", "2503,1,2,1,1,1", "", "abc", "2503,0,2,1,1,1,o",  # malformed
            "2504,1,2,1,1,1,o,extra,fields", "2505,１,2,1,1,1,o", "2506,1,2,1,1000001,1,o", "2507,0001,2,1,1,1,o",
            "2508,1,2,1,1,1,o", "2508,1,9,3,1,5,o"])
        self.assertEqual(h.decode_days(text), [
            (2500, 30, 40, 35, 9, 1, "a"), (2501, 8, 25, 15, 7, 2, "o"), (2502, 70, 80, 75, 1, 1, "o"),
            (2504, 1, 2, 1, 1, 1, "o"), (2507, 1, 2, 1, 1, 1, "o"), (2508, 1, 9, 3, 1, 5, "o")])
        many = ";".join(f"{d},1,1,1,0,0,o" for d in range(2000, 2200))
        days = h.decode_days(many)
        self.assertEqual((len(days), days[0][0], days[-1][0]), (120, 2080, 2199))
        self.assertEqual(h.decode_days(None), [])
        self.assertEqual(h.decode_days("1" * 13 + ",1,1,1,1,1,o"), [])

    def test_points_merge_within_30_minutes_and_keep_120(self):
        t = NOW
        text = f"{t + 1799},90,5,9;{t},100,10,3;{t},100,4,7;{t + 1800},50,1,1;{t + 1900},50,2,8;{t + 5000},bad,1,1;0,1,1,1"
        self.assertEqual(h.decode_points(text), [(t, 90, 10, 9), (t + 1800, 50, 2, 8)])
        self.assertEqual(h.decode_points(f"{t},100,5,9;{t + 60},90,4,2;{t + 4000},90,1,2;{t + 4060},100,8,9"),
                         [(t, 90, 5, 2), (t + 4000, 90, 8, 2)])
        many = ";".join(f"{t + i * 3600},1,1,1" for i in range(200))
        points = h.decode_points(many)
        self.assertEqual((len(points), points[0][0]), (120, t + 80 * 3600))

    def test_deposits(self):
        self.assertEqual(h.decode_deposits("3:240,1:60,1:70,0:5,10:5,2:x,4:1:2,:9,5:,6:1000000001,9:0"),
                         [(1, 70), (3, 240), (9, 0)])
        self.assertEqual(h.decode_deposits(None), [])

    def test_market_keys_match_the_server(self):
        for key in ("Mirage Raceway-Alliance", "Zul'jin-Horde", "Los-Errantes-Alliance", "R" * 64 + "-Horde",
                    "Ñ" * 64 + "-Alliance"):
            self.assertTrue(h.valid_market_key(key), key)
        for key in ("Mirage-Neutral", "-Alliance", "a|b-Alliance", "R" * 65 + "-Horde", "Reino\n-Horde", "Reino-alliance",
                    "🐉" * 33 + "-Horde", 7, None):
            self.assertFalse(h.valid_market_key(key), key)


