class Response:
    def __init__(self, body):
        self.body = body

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

    def read(self, limit):
        return self.body[:limit]


class HttpTests(unittest.TestCase):
    def test_https_only(self):
        self.assertEqual(h.validate_panel_url("https://ESPECULADOR.example.com/"), URL)
        self.assertEqual(h.validate_panel_url(URL + "/hermandad"), URL)
        self.assertEqual(h.validate_panel_url(URL + "/hermandad.html"), URL)
        for value in ("http://especulador.example.com", "http://especulador.example.com/hermandad", URL + "/api/guild/sync",
                      "https://user:pass@especulador.example.com", URL + "?k=" + KEY, URL + "#x", "https://localhost",
                      "http://127.0.0.1:8787", "ftp://especulador.example.com", "", None, "https://bad host.example"):
            with self.subTest(value=value), self.assertRaises(h.SyncError) as raised:
                h.validate_panel_url(value, env={})
            self.assertNotIn("aplicación", str(raised.exception))

    def test_local_http_only_with_the_test_switch_and_only_on_this_pc(self):
        env = {h.LOCAL_TEST_ENV: "1"}
        self.assertEqual(h.validate_panel_url("http://127.0.0.1:8787", env), "http://127.0.0.1:8787")
        self.assertEqual(h.validate_panel_url("http://localhost/hermandad", env), "http://localhost")
        self.assertEqual(h.validate_panel_url(URL, env), URL)
        for value in ("http://especulador.example.com", "http://192.168.1.2:8787", "http://user@127.0.0.1",
                      "http://127.0.0.1/api", "http://127.0.0.1?x=1"):
            with self.subTest(value=value), self.assertRaises(h.SyncError):
                h.validate_panel_url(value, env)

    def test_post_sends_the_bearer_key_to_the_guild_route_without_redirects(self):
        captured = {}
        class Opener:
            def open(self, request, timeout):
                captured.update(url=request.full_url, method=request.get_method(), timeout=timeout, body=request.data,
                                headers={k.lower(): v for k, v in request.header_items()})
                return Response(b'{"accepted":true,"duplicate":true}')
        def build(handler):
            self.assertIsInstance(handler, sync._NoRedirect)
            return Opener()
        with patch.object(h, "build_opener", build):
            self.assertEqual(h.post_guild(URL, KEY, b"{}"), {"accepted": True, "duplicate": True})
        self.assertEqual((captured["url"], captured["method"], captured["timeout"], captured["body"]),
                         (URL + "/api/guild/sync", "POST", 30, b"{}"))
        self.assertEqual(captured["headers"]["authorization"], "Bearer " + KEY)
        self.assertEqual(captured["headers"]["content-type"], "application/json; charset=utf-8")
        self.assertNotIn("content-encoding", captured["headers"])

    def test_post_refuses_plain_http_and_bad_keys_before_connecting(self):
        with patch.object(h, "build_opener", side_effect=AssertionError("no debe conectar")):
            for url, key in (("http://especulador.example.com", KEY), (URL, "esp_" + KEY[4:]), (URL, KEY + "x")):
                with self.subTest(url=url), self.assertRaises(h.SyncError) as raised:
                    h.post_guild(url, key, b"{}")
                self.assertNotIn(KEY, str(raised.exception))

    def answer(self, error):
        with patch.object(h, "build_opener") as builder:
            builder.return_value.open.side_effect = error
            with self.assertRaises(h.SyncError) as raised:
                h.post_guild(URL, KEY, b"{}")
        self.assertNotIn(KEY, str(raised.exception))
        return raised.exception

    def http(self, code, body=b"", headers=None):
        return HTTPError(URL, code, "x " + KEY, headers or {}, io.BytesIO(body))

    def test_server_answers_are_mapped_to_clear_messages(self):
        for code in (401, 403):
            self.assertIsInstance(self.answer(self.http(code, b'{"error":"La clave se ha revocado."}')), h.AuthenticationError)
        error = self.answer(self.http(400, json.dumps({"error": "Envío no válido: lo de " + KEY + "\n"}).encode()))
        self.assertIsInstance(error, h.RejectedUploadError)
        self.assertIn("«Envío no válido: lo de [clave]»", str(error))
        for code in (413, 415):
            self.assertIsInstance(self.answer(self.http(code)), h.RejectedUploadError)
        limited = self.answer(self.http(429, b'{"error":"Ya has hecho 24 envios hoy."}'))
        self.assertEqual((type(limited), limited.retry_after), (h.RetryableSyncError, 900))
        self.assertEqual(self.answer(self.http(429, headers={"Retry-After": "120"})).retry_after, 120)
        self.assertEqual(self.answer(self.http(429, headers={"Retry-After": "99999"})).retry_after, 3600)
        self.assertIn("HTTP 503", str(self.answer(self.http(503, b'{"error":"Hermandad no configurada."}'))))
        self.assertIn("redirección", str(self.answer(self.http(302))))
        self.assertIn("HTTP 500", str(self.answer(self.http(500, b"<html>" + KEY.encode()))))
        self.assertIsInstance(self.answer(URLError("secreto " + KEY)), h.RetryableSyncError)
        self.assertIsInstance(self.answer(TimeoutError()), h.RetryableSyncError)
        for body in (b"no json", b'{"accepted":false}', b"[]", b"x" * (h.MAX_RESPONSE_BYTES + 1)):
            with patch.object(h, "build_opener") as builder:
                builder.return_value.open.return_value = Response(body)
                with self.subTest(body=body[:20]), self.assertRaises(h.RetryableSyncError):
                    h.post_guild(URL, KEY, b"{}")

    def test_key_format(self):
        self.assertEqual(h.validate_key("  " + KEY + "\n"), KEY)
        for bad in ("", KEY[:-1], KEY + "A", "esp_" + KEY[4:], KEY[:10] + " " + KEY[11:], KEY[:-1] + "=", None, 5):
            with self.subTest(bad=bad), self.assertRaises(h.SyncError) as raised:
                h.validate_key(bad)
            self.assertNotIn(KEY, str(raised.exception))


