class CliTests(Quiet):
    def setUp(self):
        super().setUp()
        self.wow = self.tmp / "World of Warcraft"
        self.file = self.wow / "_forever_" / "WTF" / "Account" / "CUENTA1" / "SavedVariables" / "OroHermandad.lua"
        write(self.file, saved_variables(sample_hist(), chardb=True))
        self.home = self.tmp / "LocalAppData" / "OroHermandad"
        self.calls = []

    def poster(self, url, key, payload, timeout):
        self.calls.append((url, key, payload))
        return {"accepted": True, "duplicate": False, "rowsChanged": 1, "uploadsLeft": 1}

    def main(self, argv, answers=(), secret=KEY, protector=None, **kwargs):
        answers = iter(answers)
        def ask(prompt):
            try:
                return next(answers)
            except StopIteration:
                raise AssertionError("pregunta inesperada: " + prompt) from None
        def ask_secret(prompt):
            if secret is None:
                raise AssertionError("no debe pedir la clave")
            return secret
        options = dict(protector=protector or h.TestOnlyProtector(), home=self.home, ask=ask, ask_secret=ask_secret,
                       detect=lambda: [self.wow.resolve()], poster=self.poster, sleep=lambda s: None, clock=lambda: NOW)
        options.update(kwargs)
        return h.main(argv, **options)

    def test_first_run_asks_three_things_then_never_again(self):
        self.assertEqual(self.main(["--once"], answers=[URL + "/hermandad", "3", ""]), 0)
        self.assertEqual(len(self.calls), 1)
        self.assertEqual(self.calls[0][:2], (URL, KEY))
        self.assertEqual(self.calls[0][2], encoded(EXPECTED))
        config = json.loads((self.home / "config.json").read_text(encoding="utf-8"))
        self.assertEqual((config["url"], config["wow"]), (URL, str(self.wow.resolve())))
        self.assertIn(str(self.file), config["sources"])
        out = self.output.getvalue()
        self.assertIn("Ese número no está en la lista.", out)
        self.assertIn("Cuenta CUENTA1: envío aceptado (2 mercados, 3 objetos): 1 cambio. Te queda 1 envío hoy.", out)
        self.assertNotIn(KEY, out)
        stamp = (self.home / "config.json").stat().st_mtime_ns
        self.assertEqual(self.main(["--once"], secret=None), 0)
        self.assertEqual(len(self.calls), 1)
        self.assertIn("Sin cambios pendientes.", self.output.getvalue())
        self.assertEqual((self.home / "config.json").stat().st_mtime_ns, stamp)  # nothing new: not rewritten

    def test_unreadable_or_foreign_config_is_asked_again(self):
        self.home.mkdir(parents=True)
        for text in (json.dumps({"schema": 2, "url": URL, "wow": str(self.wow), "sources": {}}), "{roto", "[]"):
            (self.home / "config.json").write_text(text, encoding="utf-8")
            self.assertEqual(self.main(["--once"], answers=[URL, ""]), 0)
            self.assertEqual(json.loads((self.home / "config.json").read_text(encoding="utf-8"))["schema"], 1)
            (self.home / "config.json").unlink()
        self.assertIn("La configuración guardada no se puede leer", self.output.getvalue())

    def test_reset_forgets_everything(self):
        self.main(["--once"], answers=[URL, ""])
        self.assertTrue((self.home / "config.json").exists())
        self.assertEqual(self.main(["--reset"]), 0)
        self.assertFalse((self.home / "config.json").exists())
        self.assertEqual(self.main(["--reset"]), 0)
        self.assertEqual(self.main(["--once"], answers=[URL, ""]), 0)
        self.assertEqual(len(self.calls), 2)

    def test_startup_task_runs_without_prompts_and_logs_to_a_file(self):
        self.assertEqual(self.main(["--segundo-plano"], secret=None), 1)
